/* @lc app=leetcode id=3883 lang=kotlin */ class Solution { fun countArrays(digitSum: IntArray): Int = 1_000_000_007L.let { M -> IntArray(5001) { v -> v.toString().sumOf { it - '0' } }.let { ds -> digitSum.drop(1).fold(LongArray(5001) { if (ds[it] == digitSum[0]) 1L else 0L }) { prev, t -> prev.runningFold(0L) { a, b -> (a + b) % M }.let { pre -> LongArray(5001) { v -> if (ds[v] == t) pre[v + 1] else 0L } } }.sum().let { (it % M).toInt() } } } }